			playing = not playing
			$HUD/Crosshair.visible = playing and kit == "fps"
			$Player.process_mode = Node.PROCESS_MODE_INHERIT if playing else Node.PROCESS_MODE_DISABLED
			if playing: $Player/SoundFootsteps.play()
			else: $Player/SoundFootsteps.stop()
			if kit == "platformer":
