				if playing: $Player/Head/Camera.make_current()
			if not playing: camera.make_current()
			Input.mouse_mode = Input.MOUSE_MODE_CAPTURED if playing and kit == "fps" else Input.MOUSE_MODE_VISIBLE
		KEY_R:
