                        var cosine := normal.dot(projector_normal)
                        var t := clampf((cosine-float(settings.cos_reject))/maxf(0.000001,float(settings.cos_full)-float(settings.cos_reject)),0.0,1.0)
                        opacity = float(settings.opacity)*t*t*(3.0-2.0*t)
