    if name_string == "TargetA": return "target_a"
    if name_string == "TargetB": return "target_b"
    return name_string

func configure(root: Node, inputs: Dictionary) -> void:
    clear_decal()
    scene_root = root
    test_input = inputs.duplicate(true)
    elapsed = 0.0
    frame = 0
    seen_events.clear()
    event_serial = 0
