func _process(delta: float) -> void:
	if scripted:
		return
	step(minf(delta, 0.1))
	if not playing:
		var direction := float(int(Input.is_physical_key_pressed(KEY_RIGHT)) - int(Input.is_physical_key_pressed(KEY_LEFT)))
		if direction != 0:
