		assert(key in ["level", "wind_strength", "wind_direction", "wetness", "power", "health", "scan_enabled"], "Unknown parameter: " + str(key))
		state[key] = values[key]
		if key == "level": active_level = clampi(int(values[key]), 1, 3)

