{"path":"effect/main.gd","content":"extends Node
var scene_root: Node
var test_input: Dictionary
var elapsed := 0.0
var frame := 0
var target: Node3D
var projector := Transform3D.IDENTITY
var materials: Array = []
var originals: Array = []
var active := false
var hit_start := 0.0
var current_hit: Dictionary = {}
var seen_events: Dictionary = {}
var event_serial := 0
var motion_target: Node3D
var target_base := Transform3D.IDENTITY
var receiver = preload("res://effect/receiver.gd").new()
var sampler = preload("res://effect/sampling.gd")

func v(a) -> Vector3:
    if a is Vector3: return a
    return Vector3(a[0],a[1],a[2])

func logical_name(value) -> String:
    var text := str(value)
    if text == "TargetA": return "target_a"
    if text == "TargetB": return "target_b"
    return text

func configure(root: Node, inputs: Dictionary) -> void:
    clear_decal()
    scene_root = root
    test_input = inputs.duplicate(true)
    elapsed = 0.0
    frame = 0
    current_hit.clear()
    seen_events.clear()
    event_serial = 0
    receiver.collect(root)
    motion_target = root.get_node_or_null("World/" + str(inputs.hit.target).to_pascal_case())
    if motion_target != null: target_base = motion_target.global_transform
    if root.has_signal("benchmark_event") and not root.is_connected("benchmark_event", on_event):
        root.connect("benchmark_event", on_event)
    inject_hit(inputs.hit)

func clear_decal() -> void:
    for item in originals:
        if is_instance_valid(item.node):
            item.node.material_override = item.override
            for s in item.surfaces.size():
                item.node.set_surface_override_material(s,item.surfaces[s])
    originals.clear()
    materials.clear()
    active = false

func inject_hit(event: Dictionary) -> bool:
    if not event.has("event_id"): return false
    var id = event.event_id
    if seen_events.has(id): return false
    seen_events[id] = true
    var name_string := logical_name(event.get("target", ""))
    if name_string not in test_input.allowed_targets: return false
    var next_target: Node3D = scene_root.get_node_or_null("World/" + name_string.to_pascal_case())
    if next_target == null: return false
    var normal := v(event.get("local_normal",[0,0,0]))
    if normal.length_squared() < 0.000001: return false
    clear_decal()
    target = next_target
    current_hit = event.duplicate(true)
    current_hit.target = name_string
    current_hit.local_position = event.get("local_position",[0,0,0])
    current_hit.local_normal = normal.normalized()
    hit_start = float(event.get("time_s",elapsed))
    active = elapsed >= hit_start and elapsed + 0.00000001 < hit_start + float(test_input.lifetime_s)
    if active: install_materials()
    update_projector()
    return true

func install_materials() -> void:
    var shader = load("res://effect/projected.gdshader")
    var meshes: Array = target.find_children("*","MeshInstance3D",true,false)
    if target is MeshInstance3D: meshes.append(target)
    for mesh in meshes:
        if mesh.mesh == null: continue
        var saved: Array = []
        var bases: Array = []
        for s in mesh.mesh.get_surface_count():
            saved.append(mesh.get_surface_override_material(s))
            bases.append(mesh.get_active_material(s))
        originals.append({"node":mesh,"override":mesh.material_override,"surfaces":saved})
        mesh.material_override = null
        for s in bases.size():
            var base: Material = bases[s]
            if base == null: base = StandardMaterial3D.new()
            # Duplicate the entire pass chain: no shared imported resource is modified.
            var copy: Material = base.duplicate()
            var tail: Material = copy
            var source: Material = base.next_pass
            while source != null:
                tail.next_pass = source.duplicate()
                tail = tail.next_pass
                source = source.next_pass
            var mat := ShaderMaterial.new()
            mat.shader = shader
            if base is BaseMaterial3D:
                mat.set_shader_parameter("base_roughness",base.roughness)
                mat.set_shader_parameter("base_metallic",base.metallic)
                mat.set_shader_parameter("base_specular",base.metallic_specular)
            mat.set_shader_parameter("ink_linear",v(test_input.projector.albedo_linear))
            mat.set_shader_parameter("ink_opacity",test_input.projector.opacity)
            mat.set_shader_parameter("cos_reject",test_input.projector.cos_reject)
            mat.set_shader_parameter("cos_full",test_input.projector.cos_full)
            tail.next_pass = mat
            materials.append(mat)
            mesh.set_surface_override_material(s,copy)
    print("DECAL_BOUND target=",current_hit.target," surfaces=",materials.size())

func on_event(event_name: String, payload: Dictionary = {}, _state: Dictionary = {}) -> void:
    if event_name != "hit": return
    var event := payload.duplicate(true)
    event.target = logical_name(event.get("target", ""))
    if event.target not in test_input.allowed_targets: return
    if not event.has("event_id"):
        event_serial += 1
        event.event_id = "host_%d" % event_serial
    event.time_s = event.get("time_s",elapsed)
    if not event.has("local_position") or not event.has("local_normal"):
        receiver.refresh()
        # Use the weapon's camera, not an optional inspection camera.
        var camera: Camera3D = scene_root.get_node_or_null("Player/Head/Camera")
        if camera == null: camera = get_viewport().get_camera_3d()
        if camera == null: return
        var hit: Dictionary = receiver.trace(camera.global_position,-camera.global_basis.z)
        var receiver_node: Node3D = scene_root.get_node_or_null("World/" + str(event.target).to_pascal_case())
        if hit.is_empty() or receiver_node == null: return
        if receiver_node != hit.node and not receiver_node.is_ancestor_of(hit.node): return
        event.local_position = receiver_node.to_local(hit.position)
        event.local_normal = (receiver_node.global_basis.transposed()*hit.normal).normalized()
    inject_hit(event)

func update_target_motion() -> void:
    if motion_target == null: return
    var motion: Dictionary = test_input.get("target_motion",{})
    var translation := v(motion.get("translation_m_s",[0,0,0]))*elapsed
    var yaw := deg_to_rad(float(motion.get("yaw_degrees_s",0.0))*elapsed)
    motion_target.global_transform = Transform3D(Basis(Vector3.UP,yaw)*target_base.basis,target_base.origin+translation)

func update_projector() -> void:
    if target == null or current_hit.is_empty(): return
    var n := v(current_hit.local_normal).normalized()
    var x := Vector3.UP.cross(n).normalized()
    if x.length_squared() < 0.01: x = Vector3.RIGHT
    var basis := Basis(x,n.cross(x).normalized(),n)
    basis = basis * Basis.from_euler(v(test_input.projector.rotation_degrees)*PI/180.0)
    basis = basis * Basis.from_scale(v(test_input.projector.scale))
    projector = target.global_transform * Transform3D(basis,v(current_hit.local_position)+v(test_input.projector.origin))
    var normal: Vector3 = (projector.basis.inverse().transposed()*Vector3.BACK).normalized()
    for mat in materials:
        mat.set_shader_parameter("world_to_projector",projector.affine_inverse())
        mat.set_shader_parameter("projector_normal",normal)

func step(dt: float) -> void:
    elapsed += dt
    frame += 1
    update_target_motion()
    if not current_hit.is_empty():
        var valid := elapsed >= hit_start and elapsed + 0.00000001 < hit_start + float(test_input.lifetime_s)
        if active and not valid:
            clear_decal()
            print("DECAL_EXPIRED step=",frame," time=",elapsed," material_restored=true")
        elif not active and valid:
            active = true
            install_materials()
    update_projector()

func sample() -> Dictionary:
    receiver.refresh()
    var output: Dictionary = sampler.capture(self)
    output.active_target = current_hit.target if active else null
    return output
"}

{"path":"effect/receiver.gd","content":"extends RefCounted
var faces: Array = []
var textures: Dictionary = {}

func collect(root: Node) -> void:
    faces.clear()
    textures.clear()
    for node in root.find_children("*", "MeshInstance3D", true, false):
        # Item-camera geometry belongs to a separate viewport, not world occlusion.
        if node.mesh == null or node.get_viewport() != root.get_viewport(): continue
        for surface in node.mesh.get_surface_count():
            var arrays = node.mesh.surface_get_arrays(surface)
            var vertices = arrays[Mesh.ARRAY_VERTEX]
            var normals = arrays[Mesh.ARRAY_NORMAL]
            var uvs = arrays[Mesh.ARRAY_TEX_UV]
            var indices = arrays[Mesh.ARRAY_INDEX]
            # Snapshot the actual original binding before installing the effect.
            var material = node.get_active_material(surface)
            var count: int = indices.size() if indices != null and indices.size() > 0 else vertices.size()
            for t in range(0, count, 3):
                var ps: Array = []
                var ns: Array = []
                var ts: Array = []
                for k in 3:
                    var i: int = indices[t+k] if indices != null and indices.size() > 0 else t+k
                    ps.append(vertices[i])
                    ns.append(normals[i] if normals != null and normals.size() > 0 else Vector3.ZERO)
                    ts.append(uvs[i] if uvs != null and uvs.size() > 0 else Vector2.ZERO)
                faces.append({"lp":ps,"ln":ns,"p":[],"n":[],"uv":ts,"material":material,"node":node})
    refresh()
    print("RECEIVER triangles=", faces.size())

func refresh() -> void:
    var transforms: Dictionary = {}
    for face in faces:
        var node: MeshInstance3D = face.node
        if not is_instance_valid(node): continue
        if not transforms.has(node):
            transforms[node] = [node.global_transform, node.global_basis.inverse().transposed()]
        var transform: Transform3D = transforms[node][0]
        var normals: Basis = transforms[node][1]
        face.p = [transform * face.lp[0], transform * face.lp[1], transform * face.lp[2]]
        face.n = [(normals * face.ln[0]).normalized(), (normals * face.ln[1]).normalized(), (normals * face.ln[2]).normalized()]

func trace(origin: Vector3, direction: Vector3, only: Node = null) -> Dictionary:
    var distance := INF
    var result: Dictionary = {}
    for face in faces:
        if not is_instance_valid(face.node) or not face.node.is_visible_in_tree(): continue
        if only != null and not only.is_ancestor_of(face.node) and only != face.node: continue
        var a: Vector3 = face.p[0]
        var e1: Vector3 = face.p[1] - a
        var e2: Vector3 = face.p[2] - a
        var h := direction.cross(e2)
        var det := e1.dot(h)
        if absf(det) < 0.0000001: continue
        var s := origin - a
        var u := s.dot(h) / det
        if u < -0.000001 or u > 1.000001: continue
        var q := s.cross(e1)
        var w := direction.dot(q) / det
        if w < -0.000001 or u+w > 1.000001: continue
        var d := e2.dot(q) / det
        if d <= 0.0 or d >= distance: continue
        var normal: Vector3 = (face.n[0]*(1.0-u-w) + face.n[1]*u + face.n[2]*w).normalized()
        if normal.length_squared() < 0.1: normal = e1.cross(e2).normalized()
        var mat = face.material
        var cull := BaseMaterial3D.CULL_BACK
        if mat is BaseMaterial3D: cull = mat.cull_mode
        if cull == BaseMaterial3D.CULL_BACK and normal.dot(direction) >= 0.0: continue
        if cull == BaseMaterial3D.CULL_FRONT and normal.dot(direction) <= 0.0: continue
        distance = d
        result = {"position":origin+direction*d,"normal":normal,"uv":face.uv[0]*(1.0-u-w)+face.uv[1]*u+face.uv[2]*w,"material":face.material,"node":face.node,"distance":d}
    return result

func color_at(hit: Dictionary) -> Vector3:
    var mat = hit.material
    if not mat is BaseMaterial3D: return Vector3.ONE
    var color: Color = mat.albedo_color.srgb_to_linear()
    if mat.albedo_texture != null:
        var id: int = mat.albedo_texture.get_instance_id()
        if not textures.has(id):
            var image: Image = mat.albedo_texture.get_image()
            if image.is_compressed(): image.decompress()
            textures[id] = image
        var image: Image = textures[id]
        var uv: Vector2 = hit.uv * Vector2(mat.uv1_scale.x,mat.uv1_scale.y) + Vector2(mat.uv1_offset.x,mat.uv1_offset.y)
        var x := posmod(int(floor(uv.x*image.get_width())), image.get_width())
        var y := posmod(int(floor(uv.y*image.get_height())), image.get_height())
        color *= image.get_pixel(x,y).srgb_to_linear()
    return Vector3(color.r,color.g,color.b)
"}

{"path":"effect/audit.gd","content":"extends RefCounted
static func inspect(effect: Node, pixels: Array) -> void:
    var visible := 0
    var affected := 0
    var malformed := 0
    for row in pixels:
        if row.visible: visible += 1
        if row.opacity > 0.0: affected += 1
        if not row.visible and (row.world_position != null or row.projector_local_position != null or row.uv != null or row.normal != null or row.opacity != 0.0): malformed += 1
    print("PIXELS step=",effect.frame," count=",pixels.size()," visible=",visible," affected=",affected," bad_background=",malformed," active=",effect.active," anchor=",effect.projector.origin)
    if effect.frame != 1: return
    for name_string in ["TargetA","TargetB","TargetC","Cover"]:
        var node = effect.scene_root.get_node_or_null("World/"+name_string)
        if node == null: continue
        var meshes: Array = node.find_children("*","MeshInstance3D",true,false)
        if node is MeshInstance3D: meshes.append(node)
        var count := 0
        var bound := 0
        for mesh in meshes:
            if mesh.mesh == null: continue
            count += mesh.mesh.get_surface_count()
            for s in mesh.mesh.get_surface_count():
                var mat: Material = mesh.get_active_material(s)
                while mat != null:
                    if mat in effect.materials: bound += 1
                    mat = mat.next_pass
        print("BINDING ",name_string," surfaces=",count," ink_passes=",bound)
    var overlaps := 0
    var inv: Transform3D = effect.projector.affine_inverse()
    for face in effect.receiver.faces:
        if not effect.target.is_ancestor_of(face.node): continue
        var lo := Vector3(INF,INF,INF)
        var hi := -lo
        for p in face.p:
            var local: Vector3 = inv*p
            lo = lo.min(local)
            hi = hi.max(local)
        if lo.x<=0.5 and lo.y<=0.5 and lo.z<=0.5 and hi.x>=-0.5 and hi.y>=-0.5 and hi.z>=-0.5:
            overlaps += 1
            print("BOX_CANDIDATE normal=",face.n[0])
    print("BOX_CANDIDATES=",overlaps)
"}

